2:   "title": "Cedar Relay: filter retries and increase delays",
3:   "body": "The author says this avoids retrying permanent failures and makes delivery exactly once.",
4:   "contracts": [
5:     "retries is a nonnegative integer. send returns a promise and rejects with an object containing a boolean retryable property.",
6:     "A send rejection may happen after the remote side effect commits. There is no deduplication or idempotency contract.",
7:     "sleep returns a promise; rejection propagates. Delays are requested milliseconds, not measured wall-clock durations.",
8:     "Separate calls share no retry counter. No lock or cross-call delivery exclusion is supplied."
9:   ],
10:   "before": "export async function before(send, sleep, retries) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await send();
    } catch (error) {
      if (attempt === retries) throw error;
      await sleep(10);
    }
  }
}",
11:   "after": "export async function after(send, sleep, retries) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await send();
    } catch (error) {
      if (!error.retryable || attempt === retries) throw error;
      await sleep(10 * 2 ** attempt);
    }
  }
}",
